select r.id, v.* from r, (values
  ('램 & 후무스 Lamb & Hummus', '샌드위치', '부드러운 양고기와 후무스로 풍미와 식감을 즐길 수 있는 메뉴', 'https://www.subway.co.kr/upload/menu/1791792537590_jNhWrL.png', null::integer, 0::integer, array['milk', 'soy', 'wheat', 'tomato', 'sulfites', 'beef']::text[], array['egg', 'buckwheat', 'peanut', 'mackerel', 'crab', 'shrimp', 'pork', 'peach', 'walnut', 'chicken', 'squid', 'shellfish', 'pine_nut']::text[], array['파마산 오레가노', '아메리칸 치즈', '램', '후무스', '야채 4종', '치미추리 소스', '홀스래디쉬']::text[], 'Subway Korea allergy chart (subway.co.kr/sandwichAllergy)', 'Chart covers the base dish. Your bread, cheese and sauce can add more.', array[]::text[]),
